<?php
declare(strict_types=1);
require_once __DIR__ . '/assets/php/bootstrap.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$album = null; $products = []; $posts = [];
if ($id) {
    $statement = db()->prepare('SELECT al.*, ar.nombre AS artista, ar.imagen AS artista_imagen FROM album al INNER JOIN artista ar ON ar.id_artista=al.artista_id WHERE al.id_album=:id AND ar.activo=TRUE');
    $statement->execute(['id'=>$id]); $album=$statement->fetch();
    if ($album) {
        $statement=db()->prepare('SELECT id_producto,nombre,precio,imagen,stock FROM producto WHERE album_id=:id AND activo=TRUE ORDER BY fecha_actualizacion DESC');$statement->execute(['id'=>$id]);$products=$statement->fetchAll();
        $statement=db()->prepare("SELECT b.titulo,b.slug,b.`desc` FROM blog b INNER JOIN blog_album ba ON ba.blog_id=b.id_blog INNER JOIN blog_detalle bd ON bd.blog_id=b.id_blog WHERE ba.album_id=:id AND bd.estado='publicado' AND bd.fecha_publicacion<=NOW() ORDER BY bd.fecha_publicacion DESC");$statement->execute(['id'=>$id]);$posts=$statement->fetchAll();
    }
}
if (!$album) http_response_code(404);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($album['titulo'] ?? 'Álbum no disponible') ?> — SIDE B</title><link rel="stylesheet" href="assets/css/variables.css"><link rel="stylesheet" href="assets/css/global.css"><link rel="stylesheet" href="assets/css/components.css"><link rel="stylesheet" href="assets/css/home.css"><link rel="stylesheet" href="assets/css/posts.css"></head><body><?= sideb_public_header('artistas') ?><main class="container artist-profile"><p class="eyebrow">Álbum</p><?php if(!$album):?><h1>Álbum no disponible.</h1><?php else:?><div class="artist-profile-hero"><div class="artist-profile-copy"><p class="card-kicker"><?= e($album['artista']) ?> · <?= e($album['tipo']) ?></p><h1><?= e($album['titulo']) ?></h1><?php if($album['fecha_lanzamiento']):?><p>Lanzamiento: <?= e($album['fecha_lanzamiento']) ?></p><?php endif;?><a class="text-link" href="artista.php?artista=<?= rawurlencode(artist_slug($album['artista'])) ?>">Ver artista →</a></div><div class="artist-profile-art visual-surface visual-surface--artist"><?php if($album['portada']):?><img src="<?=e($album['portada'])?>" alt="<?=e($album['titulo'])?>"><?php endif;?></div></div><?php if($products):?><section class="section"><p class="eyebrow">Disponible en tienda</p><h2>Productos relacionados</h2><div class="catalog-grid"><?php foreach($products as $product):?><article class="product-card"><a class="product-image visual-surface" href="producto.php?id=<?=(int)$product['id_producto']?>"><?php if($product['imagen']):?><img src="<?=e($product['imagen'])?>" alt=""><?php endif;?></a><div class="product-info"><h3><a href="producto.php?id=<?=(int)$product['id_producto']?>"><?=e($product['nombre'])?></a></h3><strong>$<?=number_format((float)$product['precio'],2)?></strong></div></article><?php endforeach;?></div></section><?php endif;?><?php if($posts):?><section class="section"><p class="eyebrow">En SIDE B</p><h2>Historias relacionadas</h2><?php foreach($posts as $post):?><p><a class="text-link" href="publicacion.php?slug=<?=rawurlencode($post['slug'])?>"><?=e($post['titulo'])?> →</a></p><?php endforeach;?></section><?php endif;?><?php endif;?></main><?=sideb_footer()?></body></html>
